 except FileNotFoundError:break
owned=[]
for p in pathlib.Path('/proc').iterdir():
 if not p.name.isdigit() or int(p.name) in ancestors:continue
 try:
  if p.stat().st_uid!=os.getuid():continue
  cmd=(p/'cmdline').read_bytes().replace(b'\0',b' ').decode(errors='replace')
 except (FileNotFoundError,PermissionError,ProcessLookupError):continue
 if str(lab) in cmd or '/.local/opt/openshell-0.1.3/bin/' in cmd:owned.append({'pid':int(p.name),'command':cmd})
assert not owned,owned
paths=[str(p) for parent in [pathlib.Path.home()/'.config',pathlib.Path.home()/'.local/state',pathlib.Path.home()/'.local/share'] for p in parent.glob('openshell*')];assert not paths,paths
sockets=glob.glob(f'/tmp/os-{os.getuid()}-*');assert not sockets,sockets;assert not lab.exists()
